mapper.insert:
insert into LIQUIDITY_RISK_SUB ( REGIST_SEQNO,ITEM_ID,ITEM_NAME,STATUS,STATUS_DATE,CHB_SUBMIT_DEADLINE, SUBMIT_DEADLINE,SEND_STATUS,ORG_CODE,DEPT_CODE,CREATE_USER,CREATE_TIME,UPDATE_USER,UPDATE_TIME ) SELECT A.REGIST_SEQNO,A.ITEM_ID,A.ITEM_NAME,A.STATUS,A.STATUS_DATE,A.CHB_SUBMIT_DEADLINE, A.SUBMIT_DEADLINE,A.SEND_STATUS,A.ORG_CODE,A.DEPT_CODE,A.CREATE_USER,A.CREATE_TIME,A.UPDATE_USER,A.UPDATE_TIME FROM (
SELECT #{item.registSeqno,jdbcType = VARCHAR} as REGIST_SEQNO,#{item.itemId,jdbcType = VARCHAR} as ITEM_ID,#{item.itemName,jdbcType = VARCHAR} as ITEM_NAME, #{item.status,jdbcType = VARCHAR} as STATUS ,#{item.statusDate,jdbcType = DATE} as STATUS_DATE,#{item.chbSubmitDeadline,jdbcType = TIMESTAMP} as CHB_SUBMIT_DEADLINE, #{item.submitDeadline,jdbcType = TIMESTAMP} as SUBMIT_DEADLINE,#{item.sendStatus,jdbcType = VARCHAR} as SEND_STATUS ,#{item.orgCode,jdbcType = VARCHAR} as ORG_CODE,#{item.deptCode,jdbcType = VARCHAR} as DEPT_CODE,#{item.createUser,jdbcType = VARCHAR} as CREATE_USER ,sysdate as CREATE_TIME ,#{item.updateUser,jdbcType = VARCHAR} as UPDATE_USER,sysdate as UPDATE_TIME FROM dual
) A

insert into LIQUIDITY_RISK_SUB_DETAIL ( ITEM_ID, PROD_ID, REG_CODE, SOLUTIONS, OCCUR_DATE, REPLY_DATE, DESCRIBED, DISPOSE_RESULT, REMARK, ORG_CODE, DEPT_CODE, CREATE_USER, UPDATE_USER, CREATE_TIME, UPDATE_TIME ) SELECT A.ITEM_ID, A.PROD_ID, A.REG_CODE, A.SOLUTIONS, A.OCCUR_DATE, A.REPLY_DATE, A.DESCRIBED, A.DISPOSE_RESULT, A.REMARK, A.ORG_CODE, A.DEPT_CODE, A.CREATE_USER, A.UPDATE_USER, A.CREATE_TIME, A.UPDATE_TIME FROM (
SELECT #{item.itemId,jdbcType=VARCHAR} AS ITEM_ID, #{item.prodId,jdbcType=VARCHAR} AS PROD_ID, #{item.regCode,jdbcType=VARCHAR} AS REG_CODE, #{item.solutions,jdbcType=VARCHAR} AS SOLUTIONS, #{item.occurDate,jdbcType=DATE} AS OCCUR_DATE, #{item.replyDate,jdbcType=DATE} AS REPLY_DATE, #{item.described,jdbcType=VARCHAR} AS DESCRIBED, #{item.disposeResult,jdbcType=VARCHAR} AS DISPOSE_RESULT, #{item.remark,jdbcType=VARCHAR} AS REMARK, #{item.orgCode,jdbcType=VARCHAR} AS ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} AS DEPT_CODE, #{item.createUser,jdbcType=VARCHAR} AS CREATE_USER, #{item.updateUser,jdbcType=VARCHAR} AS UPDATE_USER,sysdate AS CREATE_TIME, sysdate AS UPDATE_TIME FROM dual
) A
